import {getMaintenanceList,maintenanceRemove} from "@/api/terminal";
import moment from "moment";
export default {
  data() {
    return {
      // 搜索相关
      searchForm: {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20,
      },
      // 表格相关
      dataList: [],
      loading: false,
      tableHeight: undefined,
      total: 0,
      deviceStatusList:[{
        label: '1',
        value: '在线'
      },{
        label: '0',
        value: '离线'
      }],
    };
  },
  components: {moment},
  mounted(){
    // 设置页面元素高度
    this.setPageContentHeight()
    // 设置表格高度
    this.setTableHeight()
    //加载数据
    this.onLoad();
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px'
    },
    handleQuery() {
      this.searchForm.current = 1
      this.onLoad();
    },
    handleDeleteOne(id) {
      //删除按钮
      let ids = id;
      this.handleDeleteConfirm(ids);
    },
    handleDeleteConfirm(ids) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return maintenanceRemove(ids);
        })
        .then(() => {
          this.onLoad();
          this.$message({
            type: "success",
            message: "操作成功!"
          });
        });
    },
    searchReset() {
      //重置按钮
      this.searchForm = {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20,
      }
      this.onLoad();
    },
    onLoad() {
      //加载数据
      this.loading = true;
      getMaintenanceList(this.searchForm).then(res => {
        const data = res.data;
        this.total = data.total;
        this.dataList = data.records
        this.loading = false;
      });
    },
    handleEdit(row) {
      //编辑 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          id: row.id,
          componentName: 'systemAdd',
          routerTitle: '业务系统维护编辑'
        }
      });
    },
    handleAdd() {
      //新增 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'systemAdd',
          routerTitle: '业务系统维护新增'
        }
      });
    },
  }
};
